<?php
require_once 'config/app.php'; require_roles(['admin','operator']); $pageTitle='Data Kendaraan';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$d=[trim($_POST['kode_kendaraan']),trim($_POST['nomor_polisi']),trim($_POST['merk']),trim($_POST['tipe']),$_POST['tahun']?:null,trim($_POST['warna']),trim($_POST['nomor_rangka']),trim($_POST['nomor_mesin']),$_POST['jenis'],$_POST['kapasitas']?:null,$_POST['status'],trim($_POST['keterangan'])];
 if($id){$d[]=$id;$sql="UPDATE kendaraan SET kode_kendaraan=?,nomor_polisi=?,merk=?,tipe=?,tahun=?,warna=?,nomor_rangka=?,nomor_mesin=?,jenis=?,kapasitas=?,status=?,keterangan=? WHERE id=?";}else{$sql="INSERT INTO kendaraan(kode_kendaraan,nomor_polisi,merk,tipe,tahun,warna,nomor_rangka,nomor_mesin,jenis,kapasitas,status,keterangan) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)";}
 try{$pdo->prepare($sql)->execute($d);flash('Data kendaraan berhasil disimpan.');}catch(PDOException $e){flash('Gagal menyimpan. Pastikan kode dan nomor polisi tidak duplikat.','danger');}redirect('kendaraan.php');}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$q=$pdo->prepare("SELECT COUNT(*) FROM peminjaman WHERE kendaraan_id=?");$q->execute([$id]);if($q->fetchColumn()>0)flash('Kendaraan sudah memiliki riwayat peminjaman, tidak dapat dihapus.','warning');else{$pdo->prepare("DELETE FROM kendaraan WHERE id=?")->execute([$id]);flash('Data dihapus.');}redirect('kendaraan.php');}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM kendaraan WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$rows=$pdo->query("SELECT * FROM kendaraan ORDER BY id DESC")->fetchAll();require 'includes/header.php'; ?>
<div class="d-flex justify-content-between mb-3"><h3>Data Kendaraan</h3><span class="text-muted"><?=count($rows)?> kendaraan</span></div>
<div class="card mb-4"><div class="card-header bg-white fw-bold"><?=$edit?'Edit':'Tambah'?> Kendaraan</div><div class="card-body"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><?php
$fields=['kode_kendaraan'=>'Kode Kendaraan','nomor_polisi'=>'Nomor Polisi','merk'=>'Merk','tipe'=>'Tipe','tahun'=>'Tahun','warna'=>'Warna','nomor_rangka'=>'Nomor Rangka','nomor_mesin'=>'Nomor Mesin','kapasitas'=>'Kapasitas Penumpang'];foreach($fields as $k=>$v):?><div class="col-md-4"><label class="form-label"><?=$v?></label><input class="form-control" name="<?=$k?>" value="<?=e($edit[$k]??'')?>" <?=$k==='kode_kendaraan'||$k==='nomor_polisi'||$k==='merk'?'required':''?>></div><?php endforeach;?>
<div class="col-md-4"><label class="form-label">Jenis</label><select class="form-select" name="jenis"><?php foreach(['Mobil','Motor','Lainnya'] as $v):?><option <?=$v===($edit['jenis']??'Mobil')?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['Tersedia','Perawatan','Tidak Aktif'] as $v):?><option <?=$v===($edit['status']??'Tersedia')?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-8"><label class="form-label">Keterangan</label><input class="form-control" name="keterangan" value="<?=e($edit['keterangan']??'')?>"></div><div class="col-12"><button class="btn btn-primary">Simpan</button> <a class="btn btn-light" href="kendaraan.php">Reset</a></div></form></div></div>
<div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Kode</th><th>Nomor Polisi</th><th>Kendaraan</th><th>Jenis</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['kode_kendaraan'])?></td><td><?=e($r['nomor_polisi'])?></td><td><?=e($r['merk'].' '.$r['tipe'])?></td><td><?=e($r['jenis'])?></td><td><?=status_badge($r['status'])?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$r['id']?>">Edit</a> <a class="btn btn-sm btn-outline-danger" onclick="return confirm('Hapus kendaraan ini?')" href="?delete=<?=$r['id']?>">Hapus</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center p-3">Belum ada data.</td></tr><?php endif;?></tbody></table></div></div>
<?php require 'includes/footer.php'; ?>